<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Permission; use App\Models\Role; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Validation\Rule;
class RoleController extends Controller {
 public function index(){return view('admin.roles.index',['roles'=>Role::withCount('users')->withCount('permissions')->orderBy('name')->get()]);}
 public function create(){return view('admin.roles.form',['role'=>new Role,'permissions'=>Permission::orderBy('group')->orderBy('name')->get()->groupBy('group')]);}
 public function store(Request $r){$d=$r->validate(['name'=>['required','string','max:120'],'description'=>['nullable','string'],'permissions'=>['nullable','array'],'permissions.*'=>['integer','exists:permissions,id']]);$slug=Str::slug($d['name']);$base=$slug;$suffix=2;while(Role::where('slug',$slug)->exists())$slug=$base.'-'.$suffix++;$role=Role::create(['name'=>$d['name'],'slug'=>$slug,'description'=>$d['description']??null]);$role->permissions()->sync($d['permissions']??[]);return redirect()->route('admin.roles.index')->with('success','Role created.');}
 public function edit(Role $role){return view('admin.roles.form',['role'=>$role->load('permissions'),'permissions'=>Permission::orderBy('group')->orderBy('name')->get()->groupBy('group')]);}
 public function update(Request $r,Role $role){abort_if($role->slug==='administrator'&&!$r->user()->isAdministrator(),403);$d=$r->validate(['name'=>['required','string','max:120'],'description'=>['nullable','string'],'permissions'=>['nullable','array'],'permissions.*'=>['integer','exists:permissions,id']]);$role->update(['name'=>$d['name'],'description'=>$d['description']??null]);$role->permissions()->sync($d['permissions']??[]);return back()->with('success','Role permissions updated.');}
}